import { useCallback, useEffect, useRef, useState } from "react";
import { Button } from "@/presentation/components/ui/button";
import {
	checkConversationUnlock,
	MIN_GRAMMAR_POINTS,
	MIN_VOCAB_COUNT,
} from "../../domain/conversation/services/ConversationUnlockService";
