1	// @vitest-environment jsdom
2	import { act, fireEvent, screen, waitFor } from "@testing-library/react";
3	import { describe, expect, it } from "vitest";
4	import { MIN_GRAMMAR_POINTS } from "../../domain/conversation/services/ConversationUnlockService";
5	import type { ConversationVerdict } from "../../domain/conversation/types";
6	import grammarData from "../../domain/grammar/data/grammar.json";
7	import vocabularyData from "../../domain/vocabulary/data/vocabulary.json";
8	import {
9		createdAudioUrls,
10		MIC_FIXTURE_MIME_TYPE,
11		renderWithApp,
12		revokedObjectUrls,
13		StubConversationPracticePort,
14		setMicPermission,
15	} from "../test-utils/renderWithApp";
16	import {
17		ConversationPracticePage,
18		knownWordsFor,
19	} from "./ConversationPracticePage";
20	
21	/**
22	 * A learner comfortably above both unlock thresholds — the baseline every
23	 * test in this file renders with unless it's specifically exercising the
24	 * lock itself (see the "the unlock gate" describe block below).
25	 */
26	const UNLOCKED_VOCAB: string[] = (vocabularyData as { thai: string }[])
27		.slice(0, 220)
28		.map((entry) => entry.thai);
29	const UNLOCKED_GRAMMAR: string[] = (grammarData as { id: string }[])
30		.slice(0, MIN_GRAMMAR_POINTS)
31		.map((entry) => entry.id);
32	
33	function portWithSession<T extends StubConversationPracticePort>(
34		port: T = new StubConversationPracticePort() as T,
35	): T {
36		port.session = {
37			status: "ok",
38			sessionId: "sess-1",
39			questionText: "สบายดีไหม",
40			questionAudioUrl: "blob:question-audio",
41		};
42		return port;
43	}
44	
45	function renderPage(
46		port: StubConversationPracticePort,
47		options: {
48			graduatedVocab?: readonly string[];
49			learnedGrammar?: readonly string[];
50		} = {},
51	) {
52		return renderWithApp(
53			<ConversationPracticePage />,
54			{ conversationPractice: port },
55			{
56				graduatedVocab: options.graduatedVocab ?? UNLOCKED_VOCAB,
57				learnedGrammar: options.learnedGrammar ?? UNLOCKED_GRAMMAR,
58			},
59		);
60	}
61	
62	/** Record → stop, driving the real `useMicRecorder` state machine. */
63	async function recordAndStop() {
64		const recordButton = await screen.findByRole("button", {
65			name: "Record your reply",
66		});
67		await act(async () => {
68			fireEvent.click(recordButton);
69		});
70		await act(async () => {
71			fireEvent.click(screen.getByRole("button", { name: "Stop recording" }));
72		});
73	}
74	
75	describe("ConversationPracticePage — backend unavailable", () => {
76		it("says the backend is not running and offers no record control that would do nothing", async () => {
77			// The stub port's default: every call answers `"unavailable"`.
78			renderPage(new StubConversationPracticePort());
79	
80			const alert = await screen.findByRole("alert");
81			expect(alert.textContent).toMatch(/backend is not running/i);
82			expect(screen.queryByRole("button", { name: /record/i })).toBeNull();
83		});
84	});
85	
86	describe("ConversationPracticePage — the opening question", () => {
87		it("shows the Thai question text and replays its audio on demand", async () => {
88			renderPage(portWithSession());
89	
90			expect(await screen.findByText("สบายดีไหม")).toBeTruthy();
91	
92			fireEvent.click(screen.getByRole("button", { name: "Play question" }));
93	
94			expect(createdAudioUrls()).toContain("blob:question-audio");
95		});
96	});
97	
98	describe("ConversationPracticePage — the known-vocabulary snapshot it sends", () => {
99		it("sends the learner's real learned-vocabulary set, not a placeholder list", async () => {
100			const port = portWithSession();
101	
102			// Below the unlock threshold, the page never reaches this call at all
103			// (see the "the unlock gate" tests below) — so the only known-words
104			// snapshot reachable through the real page is an above-threshold
105			// learner's real, non-empty set, asserted here to be exactly what
106			// was learned, never a placeholder.
107			renderPage(port);
108	
109			await screen.findByText("สบายดีไหม");
110	
111			expect(port.startSessionCalls).toHaveLength(1);
112			expect(new Set(port.startSessionCalls[0])).toEqual(new Set(UNLOCKED_VOCAB));
113		});
114	
115		// A learner with zero known words is unreachable through a real render of
116		// this page once the unlock gate requires a positive MIN_VOCAB_COUNT —
117		// "unlocked" and "zero known words" can never co-occur (see "the unlock
118		// gate" below). `knownWordsFor` is extracted specifically so this mapping
119		// stays unit-testable on its own: a learner with nothing learned yet must
120		// still map to a real empty array, never an omitted field or a throw.
121		it("maps a learner with no learned words to a real empty array, not an omitted field", () => {
122			const emptyVocab = { getLearnedEntries: () => [] };
123			expect(knownWordsFor(emptyVocab)).toEqual([]);
124		});
125	});
126	
127	describe("ConversationPracticePage — the unlock gate", () => {
128		it("shows the locked explanation, never the live recording UI, for a learner navigating here directly below threshold", async () => {
129			const port = portWithSession();
130	
131			renderPage(port, { graduatedVocab: [], learnedGrammar: [] });
132	
133			const alert = await screen.findByRole("alert");
134			expect(alert.textContent).toMatch(/unlocks once you know/i);
135			expect(screen.queryByRole("button", { name: /record/i })).toBeNull();
136			expect(screen.queryByText("สบายดีไหม")).toBeNull();
137			// The strongest proof "locked" isn't a label in front of a live,
138			// reachable flow: the backend is never even asked for a question.
139			expect(port.startSessionCalls).toHaveLength(0);
140		});
141	
142		it("stays locked when only the grammar threshold is unmet, even with plenty of vocabulary", async () => {
143			const port = portWithSession();
144	
145			renderPage(port, { graduatedVocab: UNLOCKED_VOCAB, learnedGrammar: [] });
146	
147			const alert = await screen.findByRole("alert");
148			expect(alert.textContent).toMatch(/grammar point/i);
149			expect(port.startSessionCalls).toHaveLength(0);
150		});
151	});
152	
153	describe("ConversationPracticePage — recording a reply", () => {
154		it("drives the recorder from idle to stopped and hands the recorded blob and session id to judgeReply", async () => {
155			const port = portWithSession();
156			port.judgement = {
157				status: "ok",
158				transcript: "สบายดีค่ะ",
159				verdict: "pass",
160				feedbackEn: "Correct.",
161			};
162			renderPage(port);
163	
164			await recordAndStop();
165	
166			await waitFor(() => expect(port.judgeCalls).toHaveLength(1));
167			const [call] = port.judgeCalls;
168			expect(call.sessionId).toBe("sess-1");
169			expect(call.questionText).toBe("สบายดีไหม");
170			expect(call.replyAudio).toBeInstanceOf(Blob);
171			expect(call.replyAudio.type).toBe(MIC_FIXTURE_MIME_TYPE);
172			expect(call.replyAudio.size).toBeGreaterThan(0);
173		});
174	});
175	
176	describe("ConversationPracticePage — verdicts and the running tally", () => {
177		const expectations: Record<ConversationVerdict, RegExp> = {
178			pass: /Good answer/,
179			fail: /Not quite/,
180			unscored: /could not be scored/i,
181		};
182	
183		for (const verdict of ["pass", "fail", "unscored"] as ConversationVerdict[]) {
184			it(`renders the ${verdict} verdict in its own words, and after advancing to the next question`, async () => {
185				const port = portWithSession();
186				port.judgement = {
187					status: "ok",
188					transcript: "สบายดีค่ะ",
189					verdict,
190					feedbackEn: "Some feedback.",
191				};
192				// A real next question, not the default `exhausted` — otherwise
193				// the page would move straight to the summary before this test
194				// could observe the per-turn verdict rendering (AC1).
195				port.nextResult = {
196					status: "ok",
197					questionText: "กำลังทำอะไรครับ",
198					questionAudioUrl: "blob:next-question",
199				};
200				renderPage(port);
201	
202				await recordAndStop();
203	
204				const rendered = await screen.findByText(expectations[verdict]);
205				expect(rendered).toBeTruthy();
206	
207				// Distinct means distinct: the other two verdicts' wording is absent.
208				for (const other of [
209					"pass",
210					"fail",
211					"unscored",
212				] as ConversationVerdict[]) {
213					if (other === verdict) continue;
214					expect(screen.queryByText(expectations[other])).toBeNull();
215				}
216	
217				// AC1: automatically advanced to the following question, no
218				// manual step, no full reload.
219				expect(await screen.findByText("กำลังทำอะไรครับ")).toBeTruthy();
220			});
221		}
222	
223		it("does not read an unscored turn as the learner's own mistake", async () => {
224			const port = portWithSession();
225			port.judgement = {
226				status: "ok",
227				transcript: "",
228				verdict: "unscored",
229				feedbackEn: "The judge's answer could not be read.",
230			};
231			// A real next question, not the default `exhausted` — otherwise the
232			// page moves straight to the summary before this test could observe
233			// the per-turn verdict note.
234			port.nextResult = {
235				status: "ok",
236				questionText: "กำลังทำอะไรครับ",
237				questionAudioUrl: "blob:next-question",
238			};
239			renderPage(port);
240	
241			await recordAndStop();
242	
243			expect(await screen.findByText(/does not count against you/i)).toBeTruthy();
244		});
245	
246		it("distinguishes pass/fail/unscored in the running tally across three turns (AC1)", async () => {
247			const port = portWithSession();
248			port.judgements.push(
249				{ status: "ok", transcript: "a", verdict: "pass", feedbackEn: "" },
250				{ status: "ok", transcript: "b", verdict: "fail", feedbackEn: "" },
251			);
252			port.judgement = {
253				status: "ok",
254				transcript: "c",
255				verdict: "unscored",
256				feedbackEn: "",
257			};
258			port.nextResults.push(
259				{ status: "ok", questionText: "q2", questionAudioUrl: "blob:q2" },
260				{ status: "ok", questionText: "q3", questionAudioUrl: "blob:q3" },
261			);
262			renderPage(port);
263	
264			await recordAndStop();
265			await screen.findByText("q2");
266			expect(screen.getByText(/1 passed \/ 1 asked/i)).toBeTruthy();
267	
268			await recordAndStop();
269			await screen.findByText("q3");
270			expect(screen.getByText(/1 passed \/ 2 asked/i)).toBeTruthy();
271	
272			await recordAndStop();
273			// unscored is named separately, never folded into "failed" or "passed".
274			await screen.findByText(/1 passed \/ 3 asked, 1 unscored/i);
275		});
276	});
277	
278	describe("ConversationPracticePage — session exhaustion (AC2)", () => {
279		it("ends the session at a summary naming all three tally components, rather than hanging on a question that will never come", async () => {
280			const port = portWithSession();
281			port.judgement = {
